llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Olsalazine, a salicylate-based molecule, had a systemic availability of only 2.3% after a 1 g oral dose in fasting healthy volunteers, demonstrating that salicylate-derived structures can have very low oral F and supporting a low-F prediction for the salicylanilide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Rebamipide, an amide drug bearing a chlorophenyl group, has oral bioavailability under 10% in humans; this amide/chlorophenyl analogy supports low systemic F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tiludronic acid, a chlorophenyl-containing drug, has an absolute oral bioavailability of 6% (range 2–11%) in healthy volunteers, showing that chlorophenyl-containing molecules can fall far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Methyl parathion, which contains a p-nitrophenyl group like the query, had an estimated maximum oral F of <1.7% in a human case, indicating that nitrophenyl-containing structures can undergo extensive presystemic loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Phosphanilic acid, an aniline derivative, had about 4% oral bioavailability in humans, supporting low systemic availability for an anilide-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Salicylic acid itself is highly bioavailable (F=0.92) after oral aspirin solution in humans, which could suggest good absorption of the salicylate scaffold; however, the query is a much larger, poorly soluble salicylanilide with nitro/chloro substituents, so this high-F evidence is less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a salicylanilide (niclosamide-like) with a nitroaniline and chlorophenol. Multiple high-transfer human/clinical records show very low oral bioavailability for salicylate-derived, chlorophenyl-containing, and nitrophenyl-containing molecules (2–10%), while the only high-F record is for the small salicylic acid scaffold and is outweighed by the query's poor solubility and larger amide structure. Therefore F is predicted to be below 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself; all evidence is from analogues.",
    "Most low-F analogues are highly ionized acids/phosphonates, whereas the query is a neutral lipophilic amide; the exact absorption-limiting mechanism may differ.",
    "The nitrophenyl-containing analogue (methyl parathion) evidence is from a single patient and is an indirect estimate.",
    "Salicylate high-F evidence is from a small carboxylic acid, not the salicylanilide amide."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

